/// <summary>
/// Example editor showing the .NET 9 breaking change fix:
/// IWindowsFormsEditorService.DropDownControl no longer accepts null.
/// Guard against null before calling DropDownControl.
/// </summary>
public class SafeDropDownEditor : UITypeEditor
{
    public override object? EditValue(ITypeDescriptorContext? context,
        IServiceProvider provider, object? value)
    {
        var editorService = provider?.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;
        if (editorService is null)
            return value;

        // .NET 9 breaking change: DropDownControl now throws ArgumentNullException if null is passed.
        // Always ensure the control is non-null before calling.
        var control = CreateDropDownControl(value);
        if (control is not null)
        {
            editorService.DropDownControl(control);
            value = GetValueFromControl(control);
            control.Dispose();
        }

        return value;
    }

    public override UITypeEditorEditStyle GetEditStyle(ITypeDescriptorContext? context)
        => UITypeEditorEditStyle.DropDown;

    private static Control? CreateDropDownControl(object? currentValue)
    {
        // Replace with your actual dropdown control creation logic.
        var listBox = new ListBox();
        listBox.Items.Add("Option1");
        listBox.Items.Add("Option2");
        return listBox;
    }

    private static object? GetValueFromControl(Control control)
    {
        if (control is ListBox lb && lb.SelectedItem is not null)
            return lb.SelectedItem.ToString();
        return null;
    }
}

